INSERT INTO knowledge_base (slug, title, category, content, keywords) VALUES ('office-hours', 'Fares desk opening hours', 'PROCESS', 'The Offshore Fares desk operates 24/7 for urgent travel within 72 hours. Standard quote requests are handled 08:00–22:00 (UTC+4), seven days a week. Requests received outside these hours are queued and prioritised automatically.', 'hours opening time weekend night');
INSERT INTO knowledge_base (slug, title, category, content, keywords) VALUES ('quote-process', 'How quotes are prepared', 'PROCESS', 'Every request receives a reference (OFF-RFQ-YYYY-NNNNNN). Our fare desk searches the best available fares; each quote is reviewed by a team member before it is sent. Fares are not guaranteed until ticketed.', 'quote process fare validity reference');
INSERT INTO knowledge_base (slug, title, category, content, keywords) VALUES ('mandatory-information', 'Information needed for a fare search', 'PROCESS', 'To search fares we need: origin and destination, travel dates (and return date for a return trip), number of passengers by type, and preferred cabin. Airline preferences and date flexibility help us find better fares.', 'information required details search');
INSERT INTO knowledge_base (slug, title, category, content, keywords) VALUES ('booking-handoff', 'What happens after you choose an option', 'PROCESS', 'When you confirm an option, our ticketing desk revalidates the fare and availability, creates the booking and contacts you for passenger details and payment through the agreed secure process. No card details should be sent by email or WhatsApp.', 'booking ticketing payment passenger details');
INSERT INTO knowledge_base (slug, title, category, content, keywords) VALUES ('changes-refunds', 'Changes, cancellations and refunds', 'POLICY', 'Change and refund conditions depend on the fare rules of each ticket. Send us the booking reference; the ticketing or refund desk will confirm the applicable penalties before anything is changed.', 'change cancel refund penalty rules');
INSERT INTO knowledge_base (slug, title, category, content, keywords) VALUES ('documents', 'Travel documents', 'PROCESS', 'Passenger names must match passports exactly. Visa and passport validity checks remain the responsibility of the travel agency; our team can share airline guidance on request.', 'passport visa documents names');
COMMIT;
